1	/* ============================================================
2	   BlogHero — blog-hero.module.css
3	   Matches: .blog-page-banner on blog.html
4	   ============================================================ */
5	
6	.section {
7	  background-color: transparent;
8	  padding-top: 4rem;
9	  padding-bottom: 4rem;
10	  font-weight: 400;
11	  text-decoration: none;
12	}
13	
14	.container {
15	  max-width: 80rem;
16	  margin-left: auto;
17	  margin-right: auto;
18	  padding-left: 2rem;
19	  padding-right: 2rem;
20	}
21	
22	/* Inner centering wrapper (.div-wrote-smoke.blogb-smoke) */
23	.inner {
24	  text-align: center;
25	  max-width: 45rem;
26	  margin-left: auto;
27	  margin-right: auto;
28	}
29	
30	/* H1 (.blog-page-title) */
31	.heading {
32	  color: var(--color-brand-navy);
33	  margin-top: 0;
34	  padding: 0;
35	  font-family: var(--font-roobert), Arial, sans-serif;
36	  font-size: 40px;
37	  font-weight: 700;
38	  line-height: 1.25;
39	  text-decoration: none;
40	}
41	
42	/* Subtitle (.h1-season-seeing.web-h1) */
43	.subtitle {
44	  color: var(--color-text-secondary);
45	  max-width: 53rem;
46	  margin-left: auto;
47	  margin-right: auto;
48	  margin-top: 0;
49	  padding-left: 1.5rem;
50	  padding-right: 1.5rem;
51	  font-family: var(--font-roobert), Arial, sans-serif;
52	  font-size: 16px;
53	  font-weight: 400;
54	  line-height: 28px;
55	  text-decoration: none;
56	}
57	
58	/* Badge grid wrapper (.web-job-attention) */
59	.badgeGridWrap {
60	  z-index: 1;
61	  justify-content: center;
62	  align-items: center;
63	  margin-top: 2rem;
64	  padding-left: 0;
65	  padding-right: 0;
66	  font-weight: 400;
67	  text-decoration: none;
68	  display: flex;
69	  position: relative;
70	}
71	
72	/* Badge grid (.web-ban-grid.mob-2grid.blog-ban-grid) — 3 boxes in a row */
73	.badgeGrid {
74	  grid-column-gap: 16px;
75	  grid-row-gap: 16px;
76	  flex: 0 auto;
77	  width: auto;
78	  display: flex;
79	}
80	
81	/* Individual badge box (.blog-ban-gridbox) */
82	.badge {
83	  grid-column-gap: 10px;
84	  grid-row-gap: 10px;
85	  background-color: #fff;
86	  border-radius: 10px;
87	  align-items: center;
88	  width: auto;
89	  padding: 15px;
90	  transition: opacity 0.5s ease, transform 0.5s ease;
91	  display: flex;
92	  box-shadow: var(--shadow-card);
93	}
94	
95	.badgeIcon {
96	  width: 24px;
97	  height: 24px;
98	  flex-shrink: 0;
99	}
100	
101	.badgeLabel {
102	  color: var(--color-text-primary);
103	  font-family: var(--font-roobert), Arial, sans-serif;
104	  font-size: 15px;
105	  font-weight: 500;
106	  line-height: 1.3;
107	  text-align: left;
108	  margin: 0;
109	}
110	
111	/* CTA button (.div-job-attention > .a-gulf-book) */
112	.ctaWrap {
113	  z-index: 1;
114	  justify-content: center;
115	  align-items: center;
116	  margin-top: 2rem;
117	  padding-left: 0;
118	  padding-right: 0;
119	  display: flex;
120	  position: relative;
121	}
122	
123	.cta {
124	  color: #fff;
125	  font-family: var(--font-roobert), Arial, sans-serif;
126	  font-size: 1rem;
127	  font-weight: 700;
128	  line-height: 1.75rem;
129	  text-decoration: none;
130	  background-image: url('/images/webflow/Group-46729-2.svg'),
131	    linear-gradient(90deg, #21cfff, #019ae6);
132	  background-position: 93%, 0 0;
133	  background-repeat: no-repeat, repeat;
134	  background-size: auto, auto;
135	  border: 2px solid transparent;
136	  border-radius: 0.75rem;
137	  justify-content: center;
138	  align-items: center;
139	  padding: 0.75rem 3rem 0.75rem 1.25rem;
140	  display: inline-flex;
141	  box-shadow: var(--shadow-card);
142	  transition: background-color 0.2s;
143	}
144	
145	.cta:hover {
146	  background-color: var(--color-brand-navy);
147	  background-image: url('/images/webflow/Group-46729-2.svg');
148	  background-repeat: no-repeat;
149	  background-size: auto;
150	}
151	
152	/* ============================================================
153	   min-width: 1280px
154	   ============================================================ */
155	@media screen and (min-width: 1280px) {
156	  .heading {
157	    color: var(--color-brand-navy);
158	    font-size: 40px;
159	    line-height: 1.25;
160	  }
161	
162	  .subtitle {
163	    margin-top: 10px;
164	  }
165	}
166	
167	/* ============================================================
168	   max-width: 991px
169	   ============================================================ */
170	@media screen and (max-width: 991px) {
171	  .badgeGrid {
172	    flex-wrap: wrap;
173	    justify-content: center;
174	  }
175	}
176	
177	/* ============================================================
178	   max-width: 767px
179	   ============================================================ */
180	@media screen and (max-width: 767px) {
181	  .heading {
182	    font-size: 2rem;
183	  }
184	
185	  .badgeGrid {
186	    grid-column-gap: 15px;
187	    grid-row-gap: 15px;
188	    grid-template-columns: 1fr 1fr;
189	    display: grid;
190	    width: 100%;
191	  }
192	
193	  .badge {
194	    width: 100%;
195	  }
196	}
197	
198	/* ============================================================
199	   max-width: 479px  (mobile)
200	   ============================================================ */
201	@media screen and (max-width: 479px) {
202	  .section {
203	    padding-top: 3rem;
204	    padding-bottom: 2.5rem;
205	  }
206	
207	  .container {
208	    padding-left: 1rem;
209	    padding-right: 1rem;
210	  }
211	
212	  .heading {
213	    font-size: 1.75rem;
214	    line-height: 1.25;
215	  }
216	
217	  .subtitle {
218	    padding-left: 0;
219	    padding-right: 0;
220	    font-size: 1rem;
221	  }
222	
223	  .badgeGrid {
224	    grid-template-columns: 1fr 1fr;
225	    display: grid;
226	    width: 100%;
227	  }
228	
229	  .badge {
230	    flex-direction: column;
231	    align-items: center;
232	    text-align: center;
233	  }
234	
235	  .badgeLabel {
236	    text-align: center;
237	    font-size: 1rem;
238	  }
239	
240	  .cta {
241	    width: 100%;
242	    justify-content: center;
243	  }
244	}
245	

