1	/* ============================================================
2	   BlogGrid — blog-grid.module.css
3	   Matches Webflow .blog-post-sec.new + .filter_grid exactly
4	   ============================================================ */
5	
6	/* blog-post-sec.new */
7	.section {
8	  background-color: transparent;
9	  background-image: none;
10	  border-bottom-right-radius: 0;
11	  border-bottom-left-radius: 0;
12	  padding: 0 3% 80px;
13	  display: block;
14	  position: relative;
15	}
16	
17	/* tabs-container → padding-vertical.padding-xlarge inner */
18	.tabsContainer {
19	  width: 100%;
20	}
21	
22	/* filt-out */
23	.filtOut {
24	  width: 100%;
25	}
26	
27	/* filter_grid: default .4fr 1fr */
28	.filterGrid {
29	  grid-column-gap: 20px;
30	  grid-row-gap: 20px;
31	  grid-template-rows: auto;
32	  grid-template-columns: 0.4fr 1fr;
33	  grid-auto-columns: 1fr;
34	  align-items: start;
35	  display: grid;
36	}
37	
38	/* ── Sidebar (filter_column.blog-filter-column) ── */
39	.filterColumn {
40	  grid-column-gap: 15px;
41	  grid-row-gap: 15px;
42	  background-color: transparent;
43	  flex-flow: column;
44	  display: flex;
45	}
46	
47	/* filter_block.search-block.blog-filter-block */
48	.searchBlock {
49	  background-color: #ffffff;
50	  border-radius: 10px;
51	  box-shadow: var(--shadow-card-soft);
52	  padding: 10px;
53	}
54	
55	/* filter_block.blog-filter-block */
56	.filterBlock {
57	  background-color: #ffffff;
58	  border-radius: 10px;
59	  box-shadow: var(--shadow-card-soft);
60	  padding: 0;
61	  overflow: hidden;
62	}
63	
64	/* filter_block-header.margin-top-0.blog-filter-header */
65	.filterBlockHeader {
66	  background-color: transparent;
67	  flex-direction: row;
68	  justify-content: space-between;
69	  align-items: center;
70	  padding: 0.5rem 0.8rem;
71	  display: flex;
72	  position: relative;
73	}
74	
75	/* filter-bar-title.margin-bottom-0 */
76	.filterBarTitle {
77	  color: var(--color-brand-navy);
78	  text-align: left;
79	  margin-top: 0;
80	  margin-bottom: 0;
81	  font-family: var(--font-roobert), Arial, sans-serif;
82	  font-size: 18px;
83	  font-weight: 700;
84	}
85	
86	/* filter_reset */
87	.filterReset {
88	  color: var(--color-brand-blue);
89	  font-family: var(--font-roobert), Arial, sans-serif;
90	  font-size: 13px;
91	  font-weight: 600;
92	  text-decoration: none;
93	  background: none;
94	  border: none;
95	  cursor: pointer;
96	  padding: 0;
97	}
98	
99	.filterReset:hover {
100	  color: var(--color-text-primary);
101	}
102	
103	/* filter_options */
104	.filterOptions {
105	  padding: 0 0.8rem 0.8rem;
106	}
107	
108	/* filter_search-field */
109	.searchField {
110	  color: var(--color-text-secondary);
111	  background-color: #ffffff;
112	  background-image: url('/images/webflow/Vector-6.svg');
113	  background-position: 94%;
114	  background-repeat: no-repeat;
115	  background-size: 1.5rem;
116	  border: 1px solid rgba(33, 207, 255, 0.23);
117	  border-radius: 10px;
118	  min-width: auto;
119	  min-height: 45px;
120	  width: 100%;
121	  margin-bottom: 0;
122	  padding: 1rem 1.5rem 1rem 1rem;
123	  font-family: var(--font-roobert), Arial, sans-serif;
124	  font-size: 1rem;
125	  box-shadow: var(--shadow-card);
126	  box-sizing: border-box;
127	}
128	
129	.searchField::placeholder {
130	  color: #9ca3af;
131	}
132	
133	.searchField:focus {
134	  border-color: var(--color-brand-cyan);
135	}
136	
137	/* Category list inside sidebar */
138	.categoryList {
139	  display: flex;
140	  flex-direction: column;
141	  gap: 6px;
142	  list-style: none;
143	  margin: 0;
144	  padding: 0;
145	}
146	
147	.categoryItem {
148	  display: flex;
149	  align-items: center;
150	  gap: 8px;
151	}
152	
153	.categoryCheckbox {
154	  width: 16px;
155	  height: 16px;
156	  border: 1.5px solid #d1d5db;
157	  border-radius: 3px;
158	  cursor: pointer;
159	  accent-color: var(--color-brand-cyan);
160	  flex-shrink: 0;
161	}
162	
163	.categoryLabel {
164	  font-family: var(--font-roobert), Arial, sans-serif;
165	  font-size: 14px;
166	  color: var(--color-text-primary);
167	  cursor: pointer;
168	  line-height: 1.4;
169	}
170	
171	.categoryLabelActive {
172	  color: var(--color-brand-blue);
173	  font-weight: 600;
174	}
175	
176	/* Top Posts */
177	.topPostsList {
178	  display: flex;
179	  flex-direction: column;
180	  gap: 12px;
181	  list-style: none;
182	  margin: 0;
183	  padding: 0;
184	}
185	
186	.topPostItem {
187	  display: flex;
188	  align-items: flex-start;
189	  gap: 10px;
190	}
191	
192	.topPostNumber {
193	  color: transparent;
194	  background-image: linear-gradient(#21cfff, #019ae6);
195	  -webkit-background-clip: text;
196	  background-clip: text;
197	  font-family: var(--font-roobert), Arial, sans-serif;
198	  font-size: 34px;
199	  line-height: 44px;
200	  font-weight: 700;
201	  flex-shrink: 0;
202	}
203	
204	.topPostInner {
205	  display: flex;
206	  flex-direction: column;
207	  flex: 1;
208	}
209	
210	.topPostTitle {
211	  color: var(--color-text-primary);
212	  text-align: left;
213	  margin: 0 0 5px;
214	  font-family: var(--font-roobert), Arial, sans-serif;
215	  font-size: 14px;
216	  font-weight: 500;
217	  line-height: 1.4;
218	  text-decoration: none;
219	}
220	
221	.topPostTitle:hover {
222	  color: var(--color-brand-blue);
223	}
224	
225	.topPostCat {
226	  color: #acacac;
227	  text-align: left;
228	  font-family: var(--font-roobert), Arial, sans-serif;
229	  font-size: 12px;
230	  margin: 0;
231	}
232	
233	/* Social icons row */
234	.socialRow {
235	  display: flex;
236	  gap: 12px;
237	  align-items: center;
238	  padding: 4px 0;
239	}
240	
241	.socialLink {
242	  display: flex;
243	  align-items: center;
244	  justify-content: center;
245	  text-decoration: none;
246	}
247	
248	.socialLink img {
249	  width: 24px;
250	  height: 24px;
251	}
252	
253	/* ── Content area (filter_content.blog-filter-content) ── */
254	.filterContent {
255	  padding-top: 10px;
256	}
257	
258	/* content_collection-list: 2-col grid */
259	.grid {
260	  grid-column-gap: 16px;
261	  grid-row-gap: 24px;
262	  grid-template-rows: auto;
263	  grid-template-columns: 1fr 1fr;
264	  grid-auto-columns: 1fr;
265	  display: grid;
266	  list-style: none;
267	  margin: 0;
268	  padding: 0;
269	}
270	
271	/* Load More btn area */
272	.loadMoreOuter {
273	  margin-top: 32px;
274	  display: flex;
275	  justify-content: center;
276	}
277	
278	/* Empty state */
279	.emptyState {
280	  display: flex;
281	  flex-direction: column;
282	  align-items: center;
283	  justify-content: center;
284	  padding: 60px 24px;
285	  text-align: center;
286	}
287	
288	.emptyIcon {
289	  width: 80px;
290	  height: auto;
291	  margin-bottom: 8px;
292	}
293	
294	.emptyText {
295	  font-family: var(--font-roobert), Arial, sans-serif;
296	  font-size: 16px;
297	  color: var(--color-text-subtle);
298	  margin: 0;
299	}
300	
301	/* ============================================================
302	   min-width: 1280px
303	   ============================================================ */
304	@media screen and (min-width: 1280px) {
305	  .filterGrid {
306	    grid-template-columns: minmax(305px, 305px) 1fr;
307	  }
308	}
309	
310	/* ============================================================
311	   max-width: 991px  (tablet)
312	   ============================================================ */
313	@media screen and (max-width: 991px) {
314	  .filterGrid {
315	    grid-column-gap: 1rem;
316	    grid-template-columns: 0.35fr 1fr;
317	  }
318	
319	  .grid {
320	    grid-row-gap: 16px;
321	    grid-template-columns: 1fr 1fr;
322	  }
323	}
324	
325	/* ============================================================
326	   max-width: 767px  (mobile portrait / large)
327	   ============================================================ */
328	@media screen and (max-width: 767px) {
329	  .filterGrid {
330	    grid-template-columns: 1fr;
331	  }
332	
333	  .filterColumn {
334	    flex-flow: column-reverse;
335	  }
336	
337	  .grid {
338	    grid-row-gap: 20px;
339	    grid-template-columns: 1fr;
340	  }
341	
342	  .section {
343	    padding-top: 0;
344	    padding-bottom: 60px;
345	  }
346	}
347	
348	/* ============================================================
349	   max-width: 479px  (small mobile)
350	   ============================================================ */
351	@media screen and (max-width: 479px) {
352	  .filterGrid {
353	    grid-template-columns: minmax(100%, 1fr);
354	  }
355	
356	  .section {
357	    padding-top: 20px;
358	    padding-bottom: 60px;
359	  }
360	}
361	

