1	/* ============================================================
2	   LEGAL CONTENT — matches Webflow .policy-page exactly
3	   Source: boldteq-v1-0.webflow.css lines 21526–21556
4	   ============================================================ */
5	
6	.page {
7	  padding: 60px 5%;
8	}
9	
10	.container {
11	  width: 100%;
12	  max-width: 900px;
13	  margin-left: auto;
14	  margin-right: auto;
15	}
16	
17	/* h1 — .policy-heading */
18	.heading {
19	  color: var(--color-text-primary);
20	  text-align: center;
21	  margin-top: 0;
22	  margin-bottom: 20px;
23	  font-family: var(--font-roobert), Arial, sans-serif;
24	  font-size: 45px;
25	  line-height: 55px;
26	  font-weight: 700;
27	}
28	
29	/* Rich-text wrapper — .paragraph.text-left.policy-para.w-richtext */
30	.richtext {
31	  color: var(--color-text-secondary);
32	  font-family: var(--font-roobert), Arial, sans-serif;
33	  font-size: 1.125rem;
34	  line-height: 28px;
35	}
36	
37	.lastUpdated {
38	  font-size: 0.875rem;
39	  color: var(--color-text-subtle);
40	  margin-bottom: 2rem;
41	  padding-bottom: 1.25rem;
42	  border-bottom: 1px solid #e5e7eb;
43	}
44	
45	/* h3 — .policy-h3 */
46	.h3 {
47	  color: var(--color-text-primary);
48	  font-family: var(--font-roobert), Arial, sans-serif;
49	  font-size: 1.25rem;
50	  font-weight: 700;
51	  margin-top: 2rem;
52	  margin-bottom: 0.75rem;
53	  line-height: 1.3;
54	}
55	
56	/* h4 — .policy-h4 */
57	.h4 {
58	  color: var(--color-text-primary);
59	  font-family: var(--font-roobert), Arial, sans-serif;
